'use strict';
const assert = require('node:assert/strict');
const S = require('./neural-connection-sockets');
let pass=0; const test=(n,f)=>{f();pass++;console.log('PASS',n)};
const conn=(state,socket,model)=>S.connect(state,{socketId:socket,adapterId:'adapter.local',adapterVersion:'1.0.0',adapterDescriptorSha256:'sha256:'+'a'.repeat(64),modelId:model,modelVersion:'1',capabilities:['text.generate','plan.review'],contextWindowTokens:32768,maxOutputTokens:4096});
let state=S.emptyState();
test('two sockets exist',()=>assert.deepEqual(S.SOCKETS,['NEURAL_A','NEURAL_B']));
test('disconnected by default',()=>assert.equal(S.snapshot(state).active.filter(x=>x.connected).length,0));
test('request on disconnected socket refuses',()=>assert.throws(()=>S.request(state,{socketId:'NEURAL_A',requester:'WALDO',purpose:'CHALLENGE',taskRef:'t',publicPacket:{x:1}}),/DISCONNECTED/));
state=conn(state,'NEURAL_A','model-a'); state=conn(state,'NEURAL_B','model-b');
test('A and B bind independent model identities',()=>assert.notEqual(state.sockets.NEURAL_A.connectionDigest,state.sockets.NEURAL_B.connectionDigest));
const base={requester:'WALDO',purpose:'CHALLENGE',taskRef:'task:1',publicPacket:{summary:'public'},requestedCapabilities:['text.generate'],maxOutputTokens:1000};
const ra=S.request(state,{...base,socketId:'NEURAL_A'});
test('request is exactly one call',()=>assert.equal(ra.maxCalls,1));
test('request carries candidate-only policy',()=>assert.equal(ra.resultPolicy,'UNTRUSTED_CANDIDATE_DATA'));
test('undeclared capability refuses',()=>assert.throws(()=>S.request(state,{...base,socketId:'NEURAL_A',requestedCapabilities:['image.generate']}),/UNDECLARED/));
test('hidden reasoning in request refuses',()=>assert.throws(()=>S.request(state,{...base,socketId:'NEURAL_A',publicPacket:{chain_of_thought:'no'}}),/PRIVATE_REASONING/));
const duo=S.dualRequest(state,{...base,purpose:'CREATIVE_VARIANT'},{...base,requester:'MIRROR',purpose:'PLAN_REVIEW'});
test('dual fanout returns independent bound requests',()=>assert.notEqual(duo.NEURAL_A.connectionDigest,duo.NEURAL_B.connectionDigest));
const result=S.acceptResult(state,ra,{output:'candidate answer',usage:{tokens:12}});
test('result is untrusted candidate data',()=>assert.equal(result.state,'UNTRUSTED_NEURAL_RESULT'));
test('result cannot merge identity or memory',()=>{assert.equal(result.identityMerge,false);assert.equal(result.memoryPromotion,'NONE')});
test('hidden reasoning in result refuses',()=>assert.throws(()=>S.acceptResult(state,ra,{output:'x',reasoning:'secret'}),/PRIVATE_REASONING/));
const disconnected=S.disconnect(state,'NEURAL_A','swap model');
test('disconnect emits receipt and clears socket',()=>{assert.equal(disconnected.state.sockets.NEURAL_A,null);assert.ok(disconnected.receipt.disconnectDigest)});
const replaced=conn(disconnected.state,'NEURAL_A','model-c');
test('late result from prior connection is stale',()=>assert.throws(()=>S.acceptResult(replaced,ra,{output:'late'}),/STALE_CONNECTION/));
console.log('RESULT',pass+'/14 PASS');
